package backend

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"math/rand/v2"
	"strings"
	"sync"
	"time"
	"unicode/utf8"

	"strix-halo-vulkan/api"
	"strix-halo-vulkan/llm"
	"strix-halo-vulkan/vk"
)

// LLMOptions is what cmd/serve's flags come to.
type LLMOptions struct {
	// Model is the GGUF checkpoint: a directory holding exactly one, or any
	// one of its shards.
