13	// POST /v1/chat/completions, buffered and streamed (LLM.md L9a).
14	//
15	// The two paths are one generation. `Complete` hands a token to a callback as
16	// it is produced and the two handlers differ only in what they do with it:
17	// the streamed one writes an SSE frame, the buffered one appends to a string
18	// builder. That is deliberate -- a server whose streaming path is a separate
19	// implementation is a server whose two answers to the same prompt eventually
20	// differ, and the difference always shows up as a whitespace or a marker that
21	// one path strips and the other does not.
22	//
23	// What this endpoint refuses is in the request validation below, and it is
24	// all the same refusal: it answers for what it did, not for what the field
25	// asked for. A `min_p` accepted and ignored is worse than a 400, because the
26	// client never learns that the knob it turned does nothing.
27	
28	// handleChatCompletions is the OpenAI chat endpoint.
29	func (s *Server) handleChatCompletions(w http.ResponseWriter, r *http.Request) {
30		if s.Completion == nil {
31			notLoaded(w, "the language model", "-llm")
32			return
33		}
34		var req CompletionRequest
35		if !decodeJSON(w, r, &req) {
36			return
37		}
38		if !validCompletion(w, &req) {
39			return
40		}
41	
42		id := "chatcmpl-" + randomID()
43		model := modelID(s.Completion, req.Model)
44		created := time.Now().Unix()
45		if req.Stream {
46			s.streamCompletion(w, r, &req, id, model, created)
47			return
48		}
49	
50		var content, reasoning strings.Builder
51		res, err := s.Completion.Complete(r.Context(), &req, func(d Delta) error {
52			content.WriteString(d.Content)
53			reasoning.WriteString(d.ReasoningContent)
54			return nil
55		})
56		if err != nil {
57			backendError(w, "chat completion", err)
58			return
59		}
60		msg := &Delta{
61			Role:             "assistant",
62			ReasoningContent: reasoning.String(),
63			Content:          content.String(),
64			ToolCalls:        res.ToolCalls,
65		}
66		usage := res.Usage
67		writeJSON(w, http.StatusOK, CompletionResponse{
68			ID:      id,
69			Object:  "chat.completion",
70			Created: created,
71			Model:   model,
72			Choices: []Choice{{Index: 0, Message: msg, FinishReason: &res.FinishReason}},
73			Usage:   &usage,
74		})
75	}
76	
77	// streamCompletion writes the generation as Server-Sent Events.
78	//
79	// **The status is committed before the first token**, which is what makes the
80	// error handling here different from every other handler in this package: by
81	// the time a run fails, 200 has been sent and there is no status left to
82	// change. So a failure becomes a final SSE frame carrying the error envelope
83	// -- the shape a client already parses -- and the log gets the rest.
84	func (s *Server) streamCompletion(w http.ResponseWriter, r *http.Request,
85		req *CompletionRequest, id, model string, created int64,
86	) {
87		stream := newSSE(w)
88		frame := func(v any) error { return stream.send("", v) }
89		chunk := func(d *Delta, finish *string) Chunk {
90			return Chunk{
91				ID: id, Object: "chat.completion.chunk", Created: created, Model: model,
92				Choices: []Choice{{Index: 0, Delta: d, FinishReason: finish}},
93			}
94		}
95	
96		// The role arrives on its own, before any content: it is what tells a
97		// client which message the deltas that follow belong to.
98		if err := frame(chunk(&Delta{Role: "assistant"}, nil)); err != nil {
99			log.Printf("api: chat completion: %v", err)
100			return
101		}
102	
103		res, err := s.Completion.Complete(r.Context(), req, func(d Delta) error {
104			return frame(chunk(&d, nil))
105		})
106		if err != nil {
107			if r.Context().Err() != nil {
108				// The client hung up mid-generation. There is nobody to tell.
109				log.Printf("api: chat completion: client cancelled")
110				return
111			}
112			log.Printf("api: chat completion: %v", err)
113			_ = frame(errorResponse{Error: errorBody{Message: err.Error(), Type: "server_error"}})
114			return
115		}
116	
117		last := &Delta{}
118		if len(res.ToolCalls) > 0 {
119			last.ToolCalls = res.ToolCalls
120		}
121		if err := frame(chunk(last, &res.FinishReason)); err != nil {
122			log.Printf("api: chat completion: %v", err)
123			return
124		}
125		// OpenAI's usage chunk: an extra frame with no choices, and only when
126		// the client asked for it.
127		if req.StreamOptions != nil && req.StreamOptions.IncludeUsage {
128			usage := res.Usage
129			if err := frame(Chunk{
130				ID: id, Object: "chat.completion.chunk", Created: created, Model: model,
131				Choices: []Choice{}, Usage: &usage,
132			}); err != nil {
133				log.Printf("api: chat completion: %v", err)
134				return
135			}
136		}
137		_ = stream.done()
138	}
139	
140	// validCompletion answers the client itself on a request this server will not
141	// serve, and reports whether the handler should carry on.
142	func validCompletion(w http.ResponseWriter, req *CompletionRequest) bool {
143		if len(req.Messages) == 0 {
144			badRequest(w, "messages is empty")
145			return false
146		}
147		for i, m := range req.Messages {
148			if kind := m.Content.NonText(); kind != "" {
149				badRequest(w, "message "+strconv.Itoa(i)+" carries a "+strconv.Quote(kind)+
150					" content block; this server has no vision model and would answer about the text alone")
151				return false
152			}
153		}
154		if req.N > 1 {
155			badRequest(w, "n is "+strconv.Itoa(req.N)+
156				"; this server generates one completion per request, and n of them would be n runs of a model sized to saturate the device")
157			return false
158		}
159		if len(req.Stop) > 0 {
160			badRequest(w, "stop sequences are not implemented; generation ends at an end-of-generation token or at max_tokens")
161			return false
162		}
163		if req.MinP != nil || req.RepeatPenalty != nil {
164			badRequest(w, "min_p and repeat_penalty are not implemented; this server's sampler is temperature, top_k and top_p")
165			return false
166		}
167		if req.ResponseFormat != nil && req.ResponseFormat.Type != "" && req.ResponseFormat.Type != "text" {
168			badRequest(w, "response_format "+strconv.Quote(req.ResponseFormat.Type)+
169				" is not implemented; there is no constrained decoding in this server yet")
170			return false
171		}
172		return true
173	}
174	
175	// modelID is what the response reports it ran. It is the backend's own id
176	// rather than the one the request asked for: a client configured for "gpt-4"
177	// against this server got this model, and saying otherwise would make a
178	// transcript unreadable a week later.
179	func modelID(b Backend, _ string) string {
180		if ms := b.Models(); len(ms) > 0 {
181			return ms[0].ID
182		}
183		return "unknown"
184	}
185	
186	// randomID is the completion's id. It is random rather than sequential
187	// because it ends up in client-side logs beside other servers' ids and
188	// nothing should be inferable from it.
189	func randomID() string {
190		var b [12]byte
191		if _, err := rand.Read(b[:]); err != nil {
192			// crypto/rand does not fail on this platform; if it ever does, a
193			// timestamp is still unique enough for a log line.
194			return strconv.FormatInt(time.Now().UnixNano(), 16)
195		}
196		return hex.EncodeToString(b[:])
197	}

