func TestChatStopAsAString(t *testing.T) {
	for _, c := range []struct {
		name string
		stop any
		want []string
	}{
		{"a bare string", "\\n\\n", []string{"\\n\\n"}},
		{"an array", []string{"\\n\\n", "END"}, []string{"\\n\\n", "END"}},
		{"null", nil, nil},
