12	// fakeLLM is the third of this package's fakes, and the reason the chat
13	// endpoint can be tested without 84 GB of weights and a minute of staging.
14	// pieces are handed to emit one at a time, which is what a real backend does
15	// a token at a time.
16	type fakeLLM struct {
17		req    *CompletionRequest
18		pieces []Delta
19		res    *CompletionResult
20		err    error
21		// failAt emits this many pieces before returning err, which is how a
22		// failure part way through a stream is tested.
23		failAt int
24	}
25	
26	func (f *fakeLLM) Models() []Model {
27		return []Model{{ID: "qwen3.8-flash-next", Object: "model", OwnedBy: "local"}}
28	}
