30	func (f *fakeLLM) Complete(_ context.Context, req *CompletionRequest,
31		emit func(Delta) error,
32	) (*CompletionResult, error) {
33		f.req = req
34		for i, p := range f.pieces {
35			if f.err != nil && i == f.failAt {
36				return nil, f.err
37			}
38			if err := emit(p); err != nil {
39				return nil, err
40			}
41		}
42		if f.err != nil {
43			return nil, f.err
44		}
45		if f.res != nil {
46			return f.res, nil
47		}
48		return &CompletionResult{
49			FinishReason: "stop",
