		"00:00:01.200 --> 00:00:02.400\nGeneral Kenobi.\n\n"
	if rec.Body.String() != wantVTT {
		t.Errorf("vtt:\n%q\nwant\n%q", rec.Body.String(), wantVTT)
	}
	if ct := rec.Header().Get("Content-Type"); !strings.HasPrefix(ct, "text/vtt") {
